import{_ as n,c as i,o as t,a3 as a}from"./chunks/framework.CoV49S2T.js";const c=JSON.parse('{"title":"Nutzungsbedingungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/terms.md","filePath":"de/guide/terms.md","lastUpdated":1786595765000}'),r={name:"de/guide/terms.md"};function u(l,e,d,s,h,o){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="nutzungsbedingungen" tabindex="-1">Nutzungsbedingungen <a class="header-anchor" href="#nutzungsbedingungen" aria-label="Permalink to &quot;Nutzungsbedingungen&quot;">​</a></h1><p>Diese Bedingungen regeln Ihre Nutzung von ClipboardxAI. Durch das Herunterladen, Installieren oder Nutzen von ClipboardxAI stimmen Sie diesen Bedingungen zu. Falls Sie nicht zustimmen, nutzen Sie die Anwendung nicht.</p><h2 id="lizenz-und-nutzung" tabindex="-1">Lizenz und Nutzung <a class="header-anchor" href="#lizenz-und-nutzung" aria-label="Permalink to &quot;Lizenz und Nutzung&quot;">​</a></h2><p>ClipboardxAI wird gemäß den Lizenzbedingungen bereitgestellt, die jeder Veröffentlichung beiliegen. Ihnen wird eine beschränkte, nicht-ausschließliche, nicht-übertragbare Lizenz zur Nutzung der Anwendung auf Ihrem Mac gemäß den Lizenzbedingungen eingeräumt.</p><h2 id="local-first-betrieb" tabindex="-1">Local-First-Betrieb <a class="header-anchor" href="#local-first-betrieb" aria-label="Permalink to &quot;Local-First-Betrieb&quot;">​</a></h2><p>ClipboardxAI läuft lokal auf Ihrem Gerät für die Zwischenablagen-Verwaltung und On-Device-Funktionen. Es wird kein Zwischenablagen-Verlauf an unsere Server übertragen.</p><h2 id="cloud-ki-anbieter" tabindex="-1">Cloud-KI-Anbieter <a class="header-anchor" href="#cloud-ki-anbieter" aria-label="Permalink to &quot;Cloud-KI-Anbieter&quot;">​</a></h2><p>ClipboardxAI kann sich mit von Ihnen konfigurierten KI-Anbietern von Drittanbietern verbinden. Ihre Nutzung dieser Anbieter unterliegt deren jeweiligen Bedingungen und Datenschutzrichtlinien. ClipboardxAI ist nicht verantwortlich für Inhalt, Verfügbarkeit oder Praktiken von Drittanbieter-Anbietern.</p><h2 id="kaufe" tabindex="-1">Käufe <a class="header-anchor" href="#kaufe" aria-label="Permalink to &quot;Käufe&quot;">​</a></h2><p>Eine Vollfunktions-Lizenz (falls angeboten) ist über den Mac App Store erhältlich. Alle Käufe werden von Apple abgewickelt. ClipboardxAI verarbeitet keine Zahlungsdaten. Die Wiederherstellung von Käufen wird bei Neuinstallationen unterstützt.</p><h2 id="benutzerpflichten" tabindex="-1">Benutzerpflichten <a class="header-anchor" href="#benutzerpflichten" aria-label="Permalink to &quot;Benutzerpflichten&quot;">​</a></h2><ul><li>Nutzen Sie ClipboardxAI rechtmäßig und in Übereinstimmung mit geltenden Regeln.</li><li>Versuchen Sie nicht, die App entgegen der Lizenz zu dekompilieren, zurückzuentwickeln oder zu modifizieren.</li><li>Sie sind für die Inhalte verantwortlich, die Sie an KI-Anbieter von Drittanbietern senden, und müssen deren Richtlinien für zulässige Nutzung einhalten.</li></ul><h2 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to &quot;Datenschutz&quot;">​</a></h2><p>Bitte lesen Sie die <a href="/de/guide/privacy.html">Datenschutzerklärung</a> für Informationen zu Datenpraktiken und Datenschutz.</p><h2 id="keine-gewahrleistung" tabindex="-1">Keine Gewährleistung <a class="header-anchor" href="#keine-gewahrleistung" aria-label="Permalink to &quot;Keine Gewährleistung&quot;">​</a></h2><p>ClipboardxAI wird „wie besehen&quot; ohne Gewährleistungen irgendeiner Art bereitgestellt. Soweit gesetzlich zulässig, schließen die Maintainers alle Gewährleistungen aus, ob ausdrücklich, stillschweigend, gesetzlich oder anderweitig, einschließlich der Marktgängigkeit und Eignung für einen bestimmten Zweck.</p><h2 id="haftungsbeschrankung" tabindex="-1">Haftungsbeschränkung <a class="header-anchor" href="#haftungsbeschrankung" aria-label="Permalink to &quot;Haftungsbeschränkung&quot;">​</a></h2><p>Soweit gesetzlich zulässig, haften die Maintainers nicht für indirekte, zufällige, besondere, Folge- oder exemplarische Schäden, die aus Ihrer Nutzung der Anwendung entstehen.</p><h2 id="beendigung" tabindex="-1">Beendigung <a class="header-anchor" href="#beendigung" aria-label="Permalink to &quot;Beendigung&quot;">​</a></h2><p>Die Ihnen eingeräumten Rechte enden automatisch, falls Sie diese Bedingungen nicht einhalten.</p><h2 id="anderungen" tabindex="-1">Änderungen <a class="header-anchor" href="#anderungen" aria-label="Permalink to &quot;Änderungen&quot;">​</a></h2><p>Wir können diese Bedingungen von Zeit zu Zeit aktualisieren. Die fortgesetzte Nutzung nach Änderungen gilt als Annahme der überarbeiteten Bedingungen.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Für Fragen zu diesen Bedingungen öffnen Sie ein Issue im Projekt-Repository: <code>https://github.com/clipboardxAI/clipboard-site/issues</code></p><p>Oder schreiben Sie uns an: <a href="mailto:clipboardxai@w3cub.com" target="_blank" rel="noreferrer">clipboardxai@w3cub.com</a></p><p><em>Zuletzt aktualisiert: 5. August 2026</em></p>',26)])])}const b=n(r,[["render",u]]);export{c as __pageData,b as default};
